function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 100000) return 'nums needs 3 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is a whole number from 1 to 100000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 queries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 3 || !query.every(v => Number.isInteger(v))) return 'Each query is three whole numbers.';
    const [type, a, b] = query;
    if (type === 1) {
      if (a < 0 || a > b || b > nums.length - 1) return 'A count query [1, l, r] needs 0 <= l <= r <= nums.length - 1.';
    } else if (type === 2) {
      if (a < 0 || a > nums.length - 1) return 'An update [2, index, val] needs 0 <= index <= nums.length - 1.';
      if (b < 1 || b > 100000) return 'An update value is between 1 and 100000.';
    } else {
      return 'Each query starts with 1 (count) or 2 (update).';
    }
  }
  return null;
}

