function countOfPeaks(nums, queries) {
  const n = nums.length;
  const tree = new Array(n + 1).fill(0);
  const peak = new Array(n).fill(0);

  const isPeak = (i) => (nums[i] > nums[i - 1] && nums[i] > nums[i + 1] ? 1 : 0);

  const add = (i, delta) => {
    for (let j = i + 1; j <= n; j += j & -j) {
      tree[j] += delta;
    }
  };

  const countBefore = (i) => {
    let sum = 0;
    for (let j = i; j > 0; j -= j & -j) {
      sum += tree[j];
    }
    return sum;
  };

  for (let i = 1; i < n - 1; i++) {
    peak[i] = isPeak(i);
    add(i, peak[i]);
  }

  const answer = [];
  for (const query of queries) {
    if (query[0] === 1) {
      const [, left, right] = query;
      if (right - left < 2) {
        answer.push(0);
      } else {
        answer.push(countBefore(right) - countBefore(left + 1));
      }
    } else {
      const [, index, value] = query;
      nums[index] = value;
      for (let i = Math.max(1, index - 1); i <= Math.min(n - 2, index + 1); i++) {
        const flag = isPeak(i);
        add(i, flag - peak[i]);
        peak[i] = flag;
      }
    }
  }
  return answer;
}

