function countOfPeaks(nums, queries) {
  // Keep a copy of the array and recount every requested range from scratch.
  const values = nums.slice();
  const result = [];
  for (const [type, a, b] of queries) {
    if (type === 2) {
      values[a] = b;
      continue;
    }
    let count = 0;
    for (let i = a + 1; i < b; i++) {
      if (values[i] > values[i - 1] && values[i] > values[i + 1]) count++;
    }
    result.push(count);
  }
  return result;
}

