function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 3 + Math.floor(rand() * 8);
  const q = large ? 2000 : 1 + Math.floor(rand() * 10);
  const top = [2, 3, 5, 100000][Math.floor(rand() * 4)];
  const value = () => 1 + Math.floor(rand() * top);
  const nums = Array.from({ length: n }, value);
  const queries = [];
  for (let k = 0; k < q; k++) {
    if (rand() < 0.5) {
      let l = Math.floor(rand() * n);
      let r = Math.floor(rand() * n);
      if (l > r) [l, r] = [r, l];
      queries.push([1, l, r]);
    } else {
      queries.push([2, Math.floor(rand() * n), value()]);
    }
  }
  return [nums, queries];
}
